package canteen;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.*;import java.util.Arrays;
public class UserManagementFrame extends JFrame {
 private final String actor,role;private JTable table;private DefaultTableModel model;
 public UserManagementFrame(String actor,String role){this.actor=actor;this.role=role;if(!AuditLog.isAdmin(role)){AuditLog.requireAdmin(null,role);dispose();return;}AppStyle.setWindowIcon(this);setTitle("PIET | User Management");setSize(850,570);setLocationRelativeTo(null);JPanel p=AppStyle.page("User management");JPanel top=new JPanel(new FlowLayout(FlowLayout.LEFT));top.setOpaque(false);JButton add=AppStyle.button("Create user",AppStyle.BLUE),reset=AppStyle.button("Reset temporary password",new Color(126,83,190)),toggle=AppStyle.button("Activate / deactivate",new Color(200,125,30)),refresh=AppStyle.button("Refresh",AppStyle.NAVY);top.add(add);top.add(reset);top.add(toggle);top.add(refresh);model=new DefaultTableModel(new String[]{"Username","Role","Active","Must change password"},0){public boolean isCellEditable(int r,int c){return false;}};table=new JTable(model);AppStyle.styleTable(table);JPanel center=new JPanel(new BorderLayout(8,8));center.setOpaque(false);center.add(top,BorderLayout.NORTH);center.add(new JScrollPane(table),BorderLayout.CENTER);p.add(center,BorderLayout.CENTER);add(p);add.addActionListener(e->create());reset.addActionListener(e->resetPassword());toggle.addActionListener(e->toggle());refresh.addActionListener(e->load());load();}
 private void load(){model.setRowCount(0);try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT username,role,active,must_change_password FROM users ORDER BY role,username")){while(r.next())model.addRow(new Object[]{r.getString(1),r.getString(2),r.getBoolean(3),r.getBoolean(4)});}catch(SQLException e){err(e);}}
 private void create(){JTextField name=new JTextField();JPasswordField pass=new JPasswordField();JComboBox<String> roleBox=new JComboBox<>(new String[]{"STAFF","ADMIN"});JPanel p=new JPanel(new GridLayout(0,1,5,5));p.add(new JLabel("Username"));p.add(name);p.add(new JLabel("Temporary password (min 10 characters)"));p.add(pass);p.add(new JLabel("Role"));p.add(roleBox);if(JOptionPane.showConfirmDialog(this,p,"Create user",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;char[] pw=pass.getPassword();if(name.getText().trim().isEmpty()||pw.length<10){JOptionPane.showMessageDialog(this,"Username and a temporary password of at least 10 characters are required.");return;}try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("INSERT INTO users(username,role,password_hash,password,must_change_password,active) VALUES(?,?,?,NULL,TRUE,TRUE)")){s.setString(1,name.getText().trim());s.setString(2,roleBox.getSelectedItem().toString());s.setString(3,SecurityUtil.hash(pw));s.executeUpdate();AuditLog.record(actor,"USER_CREATED",name.getText().trim()+" role="+roleBox.getSelectedItem());load();}catch(SQLException e){err(e);}finally{Arrays.fill(pw,'\0');}}

 private void resetPassword(){int row=table.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select a user first.");return;}String target=model.getValueAt(table.convertRowIndexToModel(row),0).toString();JPasswordField pass=new JPasswordField();if(JOptionPane.showConfirmDialog(this,new Object[]{new JLabel("Set a temporary password for "+target+" (min 10 characters):"),pass},"Reset password",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;char[] pw=pass.getPassword();if(pw.length<10){JOptionPane.showMessageDialog(this,"Password must contain at least 10 characters.");return;}try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("UPDATE users SET password_hash=?,password=NULL,must_change_password=TRUE WHERE username=?")){s.setString(1,SecurityUtil.hash(pw));s.setString(2,target);if(s.executeUpdate()!=1)throw new SQLException("User not found.");AuditLog.record(actor,"USER_PASSWORD_RESET","Temporary password set for "+target);JOptionPane.showMessageDialog(this,"Temporary password set. The user must change it at next login.");load();}catch(SQLException e){err(e);}finally{Arrays.fill(pw,'\0');}}
 private void toggle(){int row=table.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select a user first.");return;}String target=model.getValueAt(table.convertRowIndexToModel(row),0).toString();boolean active=Boolean.parseBoolean(model.getValueAt(table.convertRowIndexToModel(row),2).toString());if(target.equals(actor)){JOptionPane.showMessageDialog(this,"You cannot deactivate your own account.");return;}if(active&&model.getValueAt(table.convertRowIndexToModel(row),1).toString().equals("ADMIN")){try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement("SELECT COUNT(*) FROM users WHERE role='ADMIN' AND active=TRUE")){try(ResultSet r=q.executeQuery()){r.next();if(r.getInt(1)<=1){JOptionPane.showMessageDialog(this,"The last active administrator cannot be deactivated.");return;}}}catch(SQLException e){err(e);return;}}if(JOptionPane.showConfirmDialog(this,(active?"Deactivate ":"Activate ")+target+"?","Confirm",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("UPDATE users SET active=? WHERE username=?")){s.setBoolean(1,!active);s.setString(2,target);s.executeUpdate();AuditLog.record(actor,"USER_STATUS_CHANGED",target+" active="+(!active));load();}catch(SQLException e){err(e);}}
 private void err(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"User management error",JOptionPane.ERROR_MESSAGE);}
}
